/**
 * @function getLuckyNumbers
 * @description Lucky numbers are generated by a sieve similar to the
 *   Sieve of Eratosthenes. Starting with natural numbers, every 2nd
 *   number is removed, then every 3rd, then every 7th, etc.
 *   Sequence: 1, 3, 7, 9, 13, 15, 21, 25, 31, 33...
 * @param {number} limit - Upper limit to generate lucky numbers up to
 * @returns {number[]} - Array of lucky numbers up to limit
 * @see https://en.wikipedia.org/wiki/Lucky_number
 * @example getLuckyNumbers(20) => [1, 3, 7, 9, 13, 15]
 * @example getLuckyNumbers(50) => [1, 3, 7, 9, 13, 15, 21, 25, 31, 33, 37, 43, 49]
 */
const getLuckyNumbers = (limit) => {
  if (!Number.isInteger(limit) || limit < 1) {
    throw new TypeError('Input must be a positive integer')
  }
  let sieve = Array.from({ length: limit }, (_, i) => i + 1).filter(
    (n) => n % 2 !== 0
  )
  let i = 1
  while (i < sieve.length && sieve[i] <= sieve.length) {
    const step = sieve[i]
    sieve = sieve.filter((_, idx) => (idx + 1) % step !== 0)
    i++
  }
  return sieve
}

export { getLuckyNumbers }
